window.NPC_CHUNK_219 = [{"name":"Ghalcor Subtier 8-9","cr":11,"xp":12800,"race":"allip","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":10}],"alignment":"CE","size":"Medium","type":"undead","sub_types":["incorporeal"],"init":7,"senses":["darkvision 60 ft."],"auras":["babble (60 ft., DC 18)"],"ac":20,"ac_touch":20,"ac_flat_footed":16,"ac_mods":"+6 deflection, +3 Dex, +1 dodge","hp":147,"hd":"4d8+10d8+84","hd_value":14,"fort":10,"ref":9,"will":12,"defensive_abilities":["channel resistance +2","incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"incorporeal touch +13 (1d4 Wisdom damage/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"babble"},{"type":"touch of insanity","details":"DC 18"}],"spellsknown_caster":"oracle","spellsknown_caster_level":10,"spellsknown_concentration":16,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"greater command"},{"spell":"lesser planar binding"},{"spell":"mass inflict light wounds"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"confusion"},{"spell":"dismissal"},{"spell":"inflict critical wounds"},{"spell":"terrible remorse"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"bestow curse"},{"spell":"borrow fortune"},{"spell":"inflict serious wounds"},{"spell":"invisibility purge"},{"spell":"vermin shape I"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"desecrate"},{"spell":"grace"},{"spell":"inflict moderate wounds"},{"spell":"oracle's burden"},{"spell":"resist energy"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"bane"},{"spell":"doom"},{"spell":"endure elements"},{"spell":"inflict light wounds"},{"spell":"murderous command"},{"spell":"protection from law"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"virtue"}]}],"mystery":"outer rifts","dexterity":16,"intelligence":13,"wisdom":13,"charisma":22,"baseatk":10,"cmb":13,"cmd":30,"feats":[{"feat":"Ability Focus (touch of insanity)"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Improved Critical (incorporeal touch)"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Disable Device","value":10},{"skill":"Fly","value":18},{"skill":"Intimidate","value":19},{"skill":"Knowledge (engineering)","value":11},{"skill":"Knowledge (planes)","value":14},{"skill":"Knowledge (religion)","value":14},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":9},{"skill":"Spellcraft","value":14},{"skill":"Stealth","value":13}],"languages":["Common","Abyssal","Aklo"],"sq":["madness","oracle's curse (wrecker)","relentless compulsion","revelations (balefire, planar haze, unearthly terrain)"],"special_abilities":[{"type":"Balefire","kind":"Su","details":"Ghalcor's balefire oracle revelation allows him to burn his foes with eldritch fires drawn from the Abyss itself twice per day. As a standard action, he causes one target within 30 ft. to become wreathed in flames; the target takes 10d6 points of fire damage and is staggered for 1 round (Reflex DC 21 half and negate staggered)."},{"type":"Planar Haze","kind":"Su","details":"As a swift action, Ghalcor can fill an area with a fog cloud, like the spell of the same name, except it originates at the center of the spell effect and cannot expand beyond the spell's area."},{"type":"Relentless Compulsion","kind":"Su","details":"Ghalcor constantly tries to recalculate how he failed and why, relentlessly pursuing a perfect solution that is just out of reach. Thus, he's adept at predicting failure allowing him to re-roll any one d20 roll and taking the higher result, even after knowing the results."},{"type":"Unearthly Terrain","kind":"Su","details":": As a standard action, Ghalcor can turn one 20-foot square into difficult terrain for 1 round per level. He can use this ability 9 times per day."},{"type":"Wrecker","kind":"Su","details":"Any held objects by Ghalcor gain the broken condition when he attempts to use or equip them but regain their actual condition if employed by anyone else. If a held item is restored to unbroken condition, it becomes broken again the following round."}],"before_combat":"Ghalcor casts resist energy (fire) as soon as he detects intruders in his tower. He then waits just inside the  room's floor and casts invisibility purge when he hears the doors to area A4 open.","during_combat":"Ghalcor babbles and attacks any living creature, focusing on priests of good-aligned gods because they remind him of his life's work and tragic demise. He uses spells like confusion and greater command to slow down attackers.","morale":"Ghalcor fights until destroyed.","source":"PFS S5-13, Pathfinder RPG Advanced Player's Guide 42, Pathfinder RPG Bestiary 3 12"},{"name":"Abrikandilu Berserker","cr":6,"xp":2400,"race":"Abrikandilu","age_category":"Adult","classes":[{"class":"barbarian","level":3}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["chaotic","demon","evil","extraplanar"],"init":2,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+2 Dex, +5 natural, -2 rage","hp":79,"hd":"5d10+3d12+27","hd_value":8,"fort":10,"ref":7,"will":7,"defensive_abilities":["trap sense +1","uncanny dodge"],"immunities":["electricity","poison"],"resists":["acid 10","cold 10","fire 10"],"weaknesses":["hatred of mirrors"],"speed":[{"type":"land","speed":40}],"melee":"bite +14 (1d6+6 plus mutilation), 2 claws +14 (1d4+6)","ranged":"improvised weapon +10 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"destructive attacks"},{"type":"mutilation"},{"type":"rage","details":"9 rounds/day"},{"type":"rage powers","details":"1"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"1 abrikandilu 50%, level 1"}]},{"frequency":"3/day","spells":[{"spell":"cause fear"},{"spell":"shatter"}]}],"strength":23,"dexterity":15,"constitution":16,"intelligence":8,"wisdom":12,"charisma":11,"baseatk":8,"cmb":14,"cmb_special":"+16 sunder","cmd":24,"cmd_special":"26 vs. sunder","feats":[{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Throw Anything","type":"bonus"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+4 when jumping"},{"skill":"Appraise","value":7},{"skill":"Climb","value":17},{"skill":"Disable Device","value":13},{"skill":"Perception","value":16}],"languages":["Abyssal","Celestial","Draconic","telepathy 100 ft."],"sq":["fast movement"],"special_abilities":[{"type":"Destructive Attacks","kind":"Ex","details":"An abrikandilu's natural attacks can threaten and confirm critical hits against objects. In addition, they gain a +5 racial bonus on Strength checks made to break or destroy objects."},{"type":"Hatred of Mirrors","kind":"Ex","details":"An abrikandilu loathes the sight of its own reflection. Using a mirror grants a +5 bonus on Intimidate checks against an abrikandilu. An abrikandilu adjacent to a mirror or attacked by a mirror-carrying creature (at the GM's discretion, some shields could be considered mirrors) must attempt a DC 15 Will save at the start of its turn. If it fails, it must focus all of its actions that round on attempts to destroy the mirror."},{"type":"Mutilation","kind":"Su","details":"An abrikandilu's bite causes hideous, ugly wounds that not only mar beauty but supernaturally diminish a creature's sense of self-worth. A creature bitten by an abrikandilu must succeed at a DC 15 Fortitude save or gain a -1 penalty on all Charisma-based checks. This penalty can stack as high as a -5 penalty with multiple bites and failed saves. This lasts even after the wounds are healed; the penalty decreases by 1 point every 24 hours. This is a curse effect. The save DC is Constitution-based."}],"before_combat":"One berserker noisily begins breaking apart the control panels as the other one inspects its surroundings.","during_combat":"The abrikandilu berserker on the platform takes cover behind the control panel and continues to damage it, redirecting its attacks to nearby enemies. The other abrikandilu defends the stairs, throwing hunks of rubble and metal at distant foes. The demons delight in breaking smaller weapons, wands, and potions.","morale":"After decades of stasis, the demons are itching for a chance to destroy something. They fight to the death.","base_statistics":"When not raging, the abrikandilu demon's statistics are AC 17, touch 12, flat-footed 15; hp 63; Fort +8, Will +5; Melee bite +12 (1d6+4 plus mutilation), 2 claws +12 (1d4+4); Str 19, Con 12; CMB +12, CMD 24; Skills Climb +15.","source":"PFS S5-13, Pathfinder Campaign Setting: The Worldwound 42"},{"name":"Abrikandilu Berserker Subtier 8-9","cr":9,"xp":6400,"race":"Abrikandilu","age_category":"Adult","classes":[{"class":"barbarian","level":6}],"alignment":"CE","size":"Medium","type":"outsider","sub_types":["chaotic","demon","evil","extraplanar"],"init":3,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+3 Dex, +6 natural, -2 rage","hp":121,"hd":"5d10+6d12+50","hd_value":11,"fort":12,"ref":9,"will":8,"defensive_abilities":["improved uncanny dodge","trap sense +2"],"immunities":["electricity","poison"],"resists":["acid 10","cold 10","fire 10"],"weaknesses":["hatred of mirrors"],"speed":[{"type":"land","speed":40}],"melee":"heavy pick +17 (1d6+9/x4), bite +12 (1d6+3 plus mutilation)","ranged":"improvised weapon +14 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"destructive attacks"},{"type":"mutilation"},{"type":"rage","details":"15 rounds/day"},{"type":"rage powers","details":"knockback, raging climber +6, smasher"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"1 abrikandilu 50%, level 1"}]},{"frequency":"3/day","spells":[{"spell":"cause fear"},{"spell":"shatter"}]}],"strength":23,"dexterity":16,"constitution":16,"intelligence":8,"wisdom":12,"charisma":11,"baseatk":11,"cmb":17,"cmb_special":"+21 sunder","cmd":28,"cmd_special":"30 vs. sunder","feats":[{"feat":"Greater Sunder"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Throw Anything","type":"bonus"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":11,"special":"+4 when jumping"},{"skill":"Appraise","value":7},{"skill":"Climb","value":26},{"skill":"Disable Device","value":17},{"skill":"Perception","value":19}],"languages":["Abyssal","Celestial","Draconic","telepathy 100 ft."],"sq":["fast movement"],"gear":"mwk studded leather, heavy pick, amulet of natural armor +1, thieves' tools","before_combat":"One abrikandilu noisily begins breaking apart the control panels as the other one inspects its surroundings.","during_combat":"The abrikandilu berserker on the platform takes cover behind the control panel and continues to damage it, redirecting its attacks to nearby enemies. The other abrikandilu defends the stairs, throwing hunks of rubble and metal at distant foes. The demons delight in breaking weapons, armor, wands, and potions as well as using the knockback rage ability to push enemies off the stairs and platform.","morale":"After decades of stasis, the demons are itching for a chance to destroy something. They fight to the death.","base_statistics":"When not raging, the abrikandilu demon's statistics are AC 19, touch 13, flat-footed 16; hp 99; Fort +10, Will +6; Melee heavy pick +15/+10/+5 (1d6+6/x4), bite +10 (1d6+2 plus mutilation); Str 19, Con 12; CMB +15, CMD 28; Skills Climb +18.","source":"PFS S5-13"},{"name":"Feral Howler","cr":5,"xp":1600,"race":"howler","age_category":"Adult","alignment":"CE","size":"Large","type":"outsider","sub_types":["chaotic","evil","extraplanar"],"templates_applied":"advanced","init":7,"senses":["darkvision 60 ft."],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 Dex, +6 natural, -1 size","hp":51,"hd":"6d10+18","hd_value":6,"fort":8,"ref":8,"will":4,"defensive_abilities":["quill defense"],"speed":[{"type":"land","speed":60}],"melee":"bite +10 (1d8+5), quills +5 (1d4+2 plus pain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"howl"}],"strength":20,"dexterity":17,"constitution":17,"intelligence":6,"wisdom":14,"charisma":13,"baseatk":6,"cmb":12,"cmd":25,"cmd_special":"29 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":9,"special":"+12 when jumping"},{"skill":"Climb","value":11},{"skill":"Perception","value":14},{"skill":"Stealth","value":8}],"languages":["Abyssal (can't speak)"],"special_abilities":[{"type":"Howl","kind":"Su","details":"A howler's constant howling is a grating, exhausting baying that can drive listeners insane. All beings other than outsiders within 120 ft. of a howling howler must succeed at a DC 14 Will save or become cursed by the creature's howl. Once a creature becomes cursed in this way, it takes no additional penalty for being exposed to additional howlers' howls until the current howler curse is lifted. This is a sonic mind-affecting effect. The save DC is Charisma-based. Howler Howl: Curse-howl; save Will DC 14 negates; frequency 1/hour; effect 1 Wis damage; cure 1 save."},{"type":"Pain","kind":"Ex","details":"Whenever a creature takes damage from a howler's quill attack or its quill defense, that creature must make a successful 16 Reflex save or one quill breaks off in its flesh, causing the target to become sickened until all embedded quills are removed. Removing one quill requires a successful DC 15 Heal check made as a full-round action. For every 5 by which the check is exceeded, one additional quill can be removed. On a failed check, a quill is still removed, but the process deals 1d4+1 points of damage to the victim. The save DC is Dexterity-based."},{"type":"Quill Defense","kind":"Ex","details":"Any creature that strikes a howler with a non-reach melee weapon, unarmed strike, or natural weapon takes 1d4+1 points of piercing damage from the howler's quills and suffers from the howler's pain attack."}],"before_combat":"Sensing prey nearby, the howlers begin to close in on the outbuilding by using the rain to conceal their approach. The howler in the haystack observes the Pathfinders and howls and attacks when the first PC enters the stable, signaling its kin to join the assault.","during_combat":"The howlers utter mind-shattering howls immediately upon initiating combat and continue to howl for the duration of combat. They fight with pack tactics, attempting to surround and overwhelm the weakest-looking PC.","morale":"The howlers fight until reduced to 15 or fewer hit points, at which time they attempt to flee into the wilderness.","source":"PFS S5-14, Pathfinder RPG Bestiary 2 159"},{"name":"Four-Armed Gargoyle","cr":9,"xp":6400,"race":"Four-Armed Gargoyle","age_category":"Adult","alignment":"CE","size":"Large","type":"monstrous humanoid","sub_types":["earth"],"init":1,"senses":["darkvision 60 ft."],"ac":24,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+1 Dex, +14 natural, -1 size","hp":105,"hd":"10d10+50","hd_value":10,"fort":10,"ref":8,"will":9,"dr":"10/magic","speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"bite +15 (1d8+6), 4 claws +15 (1d6+6/19-20), gore +15 (1d4+6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d6+6"}],"strength":23,"dexterity":12,"constitution":20,"intelligence":8,"wisdom":15,"charisma":11,"baseatk":10,"cmb":17,"cmd":28,"feats":[{"feat":"Great Fortitude"},{"feat":"Hover"},{"feat":"Improved Critical (claws)"},{"feat":"Power Attack"},{"feat":"Skill Focus (Fly)"}],"skills":[{"skill":"Fly","value":18},{"skill":"Perception","value":15},{"skill":"Stealth","value":10}],"languages":["Common","Terran"],"sq":["freeze"],"special_abilities":[{"type":"Freeze","kind":"Ex","details":"A gargoyle can hold itself so still it appears to be a statue. A gargoyle that uses freeze can take 20 on Stealth checks to hide in plain sight as a stone statue."}],"before_combat":"The gargoyle uses its freeze special ability to blend in with the fountain's statuary. If the PCs repeat the phrase above, the gargoyle guardian remains motionless and ignores the PCs' presence within Ostergarde.","during_combat":"The gargoyle attempts to get in a position to attack as many targets in a single round as possible, but uses the room's two-story layout to its advantage if the PCs are spread out in such a way that hit-and-run tactics work more in the guardian's favor.","morale":"The gargoyle fights until reduced below 20 hit points, at which time it flees Ostergarde, only to return when the geas effect forces it back. If at any time the PCs speak the phrase above, the gargoyle guardian immediately surrenders and retakes its position at the fountain. The gargoyle doesn't attack any creature that has previously spoken the pass phrase.","source":"PFS S5-14"},{"name":"Vaga Underbough","cr":4,"xp":1200,"race":"halfling","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":1},{"class":"sorcerer","level":4}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["halfling"],"init":3,"ac":16,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 armor, +3 Dex, +1 size","hp":34,"hd":"1d8+4d6+14","hd_value":5,"fort":4,"ref":7,"will":4,"save_mods":"+1 vs. traps, +2 vs. fear, +2 vs. poison","resists":["electricity 5"],"speed":[{"type":"land","speed":20}],"melee":"dagger +6 (1d3-1/19-20)","ranged":"dagger +6 (1d3-1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":4,"spellsknown_concentration":7,"spellsknown":[{"spell_level":2,"spell_slots":4,"spells":[{"spell":"summon monster II"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cause fear"},{"spell":"disguise self"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"resistance"}]}],"bloodline":"abyssal","strength":8,"dexterity":16,"constitution":14,"intelligence":12,"wisdom":8,"charisma":17,"baseatk":2,"cmb":0,"cmd":13,"feats":[{"feat":"Childlike"},{"feat":"Deceitful"},{"feat":"Eschew Materials"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":11,"special":"-4 when jumping"},{"skill":"Bluff","value":13},{"skill":"Climb","value":1},{"skill":"Disguise","value":13},{"skill":"Linguistics","value":5},{"skill":"Perception","value":7},{"skill":"Spellcraft","value":5},{"skill":"Stealth","value":13}],"languages":["Common","Abyssal","Halfling","Infernal"],"sq":["bloodline arcana (summoned creatures gain DR 2/good)","trapfinding +1"],"gear":"leather armor, dagger, boots of levitation, potion of gaseous form, wand of misdirection (CL 12th, 6 charges), shadow essence (2 doses)","before_combat":"Vaga attempts to position herself in the most advantageous location while her disguise is still in effect. She ensures that her dagger is coated in a dose of shadow essence whenever possible so her first attack with the weapon will be deadly.","during_combat":"Vaga prefers deception and capitalizing on her targets' moments of weakness rather than open combat, but when forced to fight, she does so with the fury expected of a killer of her renown. If adjacent to a flat- footed foe at the start of combat, she initiates with a sneak attack; otherwise, she activates her boots of levitation immediately, hovering above her enemies to avoid melee attacks. While she has a 10% arcane spell failure chance from her leather armor, she nevertheless knows that her strength is in her spellcasting rather than physical damage. Thus, she lets her yeth hound minion fight in her stead while she casts offensive spells from range. If the hound appears near death, Vaga casts summon monster II to bring a fiendish giant spider to her aid.","morale":"Vaga is overwhelmed by her urge to kill, and even when her carefully crafted plans fall apart, she can't bring herself to surrender or relent until all her enemies are dead. As such, she fights to the death.","source":"PFS S5-14"},{"name":"Vaga Underbough Subtier 6-7","cr":8,"xp":4800,"race":"halfling","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":1},{"class":"sorcerer","level":8}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["halfling"],"init":3,"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+4 armor, +3 Dex, +1 dodge, +4 shield, +1 size","hp":82,"hd":"1d8+8d6+48","hd_value":9,"fort":7,"ref":8,"will":6,"save_mods":"+1 vs. traps, +2 vs. fear, +2 vs. poison","resists":["electricity 5"],"speed":[{"type":"land","speed":20}],"melee":"dagger +8 (1d3-1/19-20)","ranged":"dagger +8 (1d3-1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":8,"spellsknown_concentration":12,"spellsknown":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"summon monster IV"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"deep slumber"},{"spell":"rage"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"bull's strength"},{"spell":"false life"},{"spell":"invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"cause fear"},{"spell":"disguise self"},{"spell":"expeditious retreat"},{"spell":"magic missile"},{"spell":"ray of enfeeblement"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"resistance"}]}],"bloodline":"abyssal","strength":8,"dexterity":16,"constitution":14,"intelligence":12,"wisdom":8,"charisma":18,"baseatk":4,"cmb":2,"cmd":16,"feats":[{"feat":"Childlike"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Great Fortitude"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":14,"special":"-4 when jumping"},{"skill":"Bluff","value":18},{"skill":"Climb","value":1},{"skill":"Disguise","value":18},{"skill":"Linguistics","value":5},{"skill":"Perception","value":7},{"skill":"Spellcraft","value":6},{"skill":"Stealth","value":13}],"languages":["Common","Abyssal","Halfling","Infernal"],"sq":["bloodline arcana (summoned creatures gain DR 4/good)","trapfinding +1"],"gear":"glamered +2 leather armor, dagger, boots of levitation, potion of gaseous form, wand of misdirection (CL 12th, 6 charges), shadow essence (2 doses)","before_combat":"Vaga attempts to position herself in the most advantageous location while her disguise is still in effect. She ensures that her dagger is coated in a dose of shadow essence whenever possible so that her first attack with the weapon will be deadly. At the soon as she is aware of the PCs' presence, Vaga casts false life, and she casts shield immediately before entering area D5, knowing combat within is imminent (as long as she can do so without being seen or heard by a PC).","during_combat":"Vaga prefers deception and capitalizing on her targets' moments of weakness rather than open combat, but when forced to fight, she does so with the fury expected of a killer of her renown. If adjacent to a flat-footed foe at the start of combat, she initiates with a sneak attack; otherwise, she activates her boots of levitation immediately, hovering above her enemies to avoid melee attacks. Although she has a 10% arcane spell failure chance as a result of wearing leather armor, she nevertheless knows that her strength is in her spellcasting rather than physical damage. Thus, she lets her yeth hound minions fight in her stead while she casts offensive spells from range. After one of the hounds is defeated, Vaga casts summon monster IV to bring 1d3 dretches to her aid (or 1d3 fiendish dire bats if more than half of the PCs are flying).","morale":"Vaga is overwhelmed by her urge to kill, and even when her carefully crafted plans fall apart, she can't bring herself to surrender or relent until all her enemies are dead. As such, she fights to the death.","base_statistics":"Without the benefit of false life and shield, Vaga has the following statistics: AC 19, touch 15, flat-footed 15; hp 69.","source":"PFS S5-14"},{"name":"Yjalk","cr":1,"xp":400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":2}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":15,"ac_touch":9,"ac_flat_footed":14,"ac_mods":"+6 armor, +1 Dex, -2 rage","hp":28,"hd":"2d12+10","hd_value":2,"fort":7,"ref":1,"will":3,"defensive_abilities":["uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"mwk greatsword +8 (2d6+7)","ranged":"shortbow +3 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"8 rounds/day"},{"type":"rage powers","details":"powerful blow"}],"strength":21,"dexterity":13,"constitution":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":2,"cmb":7,"cmd":16,"feats":[{"feat":"Cleave"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":6},{"skill":"Perception","value":6},{"skill":"Profession (sailor)","value":3},{"skill":"Survival","value":6},{"skill":"Swim","value":6}],"languages":["Common","Skald"],"sq":["fast movement"],"gear":"breastplate, mwk greatsword, shortbow with 20 arrows, sunrod, 12 gp, oil of magic weapon, potions of cure light wounds (2), acid, holy water","during_combat":"Yjalk directs his crew to attack any spellcasters and challenges the  strongest-looking PC to face him. He begins raging and strikes with Power Attack and powerful blow to end the fight quickly. He uses his oil of magic weapon only if he cannot consistently hit an opponent.","morale":"Yjalk drinks a potion of cure light wounds if he has 12 or fewer hit points but only if he's not already engaged in melee combat with the enemy. If Yjalk has 12 or fewer hit points and has only one ally remaining, he orders a fighting retreat.","base_statistics":"When not raging, Yjalk's statistics are AC 17, touch 11, flat-footed 16; hp 24; Fort +5, Will +1; Melee mwk greatsword +5 (2d6+4/19-20); Str 17, Con 14; CMB +5; Skills Climb +4, Swim +4.","source":"PFS S5-15"},{"name":"Yjalk Subtier 4-5","cr":4,"xp":1200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":5}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+7 armor, +1 Dex, +1 dodge, -2 rage","hp":63,"hd":"5d12+25","hd_value":5,"fort":9,"ref":3,"will":5,"defensive_abilities":["improved uncanny dodge","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk greatsword +12 (2d6+9/19-20)","ranged":"mwk shortbow +7 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"14 rounds/day"},{"type":"rage powers","details":"powerful blow, quick reflexes"}],"strength":22,"dexterity":13,"constitution":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":5,"cmb":11,"cmd":21,"feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":11},{"skill":"Perception","value":9},{"skill":"Profession (sailor)","value":6},{"skill":"Survival","value":9},{"skill":"Swim","value":11}],"languages":["Common","Skald"],"sq":["fast movement"],"gear":"+1 breastplate, mwk greatsword, mwk shortbow with 20 arrows, cloak of resistance +1, sunrod (2), 10 gp, +1 arrows (5), oil of magic weapon, potions of cure light wounds (2), holy water","during_combat":"Yjalk directs his crew to attack any spellcasters and challenges the strongest-looking PC to face him. He begins raging and strikes with Power Attack and powerful blow to end the fight quickly. He uses his oil of magic weapon only if he cannot consistently hit an opponent.","morale":"Yjalk drinks a potion of cure light wounds if he has 20 or fewer hit points but only if he's not already engaged in melee combat with the enemy. If Yjalk has 20 or fewer hit points and has only one ally remaining, he orders a fighting retreat.","base_statistics":"When not raging, Yjalk's statistics are AC 19, touch 12, flat-footed 17; hp 53; Fort +7, Will +3; mwk greatsword +10 (2d6+6/19-20); Str 18, Con 14; CMB +9; Skills Climb +9, Swim +9.","source":"PFS S5-15"},{"name":"Sage Of Plagues","cr":4,"xp":1200,"race":"Mythic allip","age_category":"Adult","alignment":"CE","size":"Medium","type":"undead","sub_types":["incorporeal","mythic"],"init":5,"init_special":"/-15, dual initiative","senses":["darkvision 60 ft."],"auras":["babble (60 ft., DC 16)"],"ac":15,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+4 deflection, +1 Dex","hp":50,"hd":"4d8+32","hd_value":4,"fort":5,"ref":4,"will":4,"defensive_abilities":["channel resistance +2","incorporeal","poisonous blood (insanity mist)"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"incorporeal touch +4 (1d4 Wisdom damage)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"babble"},{"type":"mythic power","details":"2/day, surge +1d6"},{"type":"simple divine spellcasting"},{"type":"touch of insanity"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"bane"},{"spell":"bestow curse"},{"spell":"disfiguring touch"},{"spell":"inflict moderate wounds"}]}],"dexterity":12,"intelligence":11,"wisdom":11,"charisma":18,"baseatk":3,"cmb":4,"cmd":18,"feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes","type":"mythic"}],"skills":[{"skill":"Fly","value":16},{"skill":"Intimidate","value":11},{"skill":"Perception","value":7},{"skill":"Stealth","value":8}],"languages":["Common","Aklo"],"sq":["madness"],"special_abilities":[{"type":"Poisonous Blood","kind":"Ex","details":"Any creature that confirms a critical hit against the allip with a piercing or slashing melee weapon breaks off a piece of its mad essence. Melee weapons with reach don't endanger their users in this way. The attacker briefly becomes enveloped by a cloud of insanity mist (inhaled; save Fort DC 15; frequency 1/round for 6 rounds; effect 1d3 Wis; cure 1 save)."}],"during_combat":"The Sage of Plagues begins combat by debilitating one or more enemies with a spell-like ability and then attacks anyone holding a shard of the shattered ruby or a nearby foe. So long as it has spell-like abilities remaining, the Sage of Plagues alternates between using those and its maddening touch. It prefers to use bestow curse and disfiguring touch on creatures it knows can hurt it, and it saves inflict moderate wounds to heal itself. It pursues fleeing enemies but doesn't go outside.","morale":"The sage fights until destroyed.","source":"PFS S5-15, Pathfinder RPG Bestiary 3 12, Pathfinder RPG Mythic Adventures 226"},{"name":"Lesser Hound Of Tindalos","cr":5,"xp":1600,"race":"Lesser Hound Of Tindalos","age_category":"Adult","alignment":"NE","size":"Medium","type":"outsider","sub_types":["evil","extraplanar"],"init":8,"senses":["darkvision 120 ft."],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":52,"hd":"7d10+14","hd_value":7,"fort":7,"ref":9,"will":6,"dr":"5/magic","immunities":["mind-affecting effects","poison"],"speed":[{"type":"land","speed":40}],"melee":"bite +11 (2d6+2), 2 claws +11 (1d8+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ripping gaze"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"}]},{"frequency":"at-will","spells":[{"spell":"fog cloud"},{"spell":"locate creature"}]},{"frequency":"3/day","spells":[{"spell":"dimensional anchor"},{"spell":"discern location"},{"spell":"greater scrying"},{"spell":"invisibility"}]}],"strength":14,"dexterity":19,"constitution":14,"intelligence":14,"wisdom":19,"charisma":13,"baseatk":7,"cmb":9,"cmd":23,"feats":[{"feat":"Blind-Fight"},{"feat":"Improved Initiative"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":13,"special":"+4 jump"},{"skill":"Intimidate","value":10},{"skill":"Knowledge (arcana)","value":11},{"skill":"Knowledge (geography)","value":11},{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":14},{"skill":"Survival","value":13}],"languages":["Aklo"],"sq":["angled entry","otherworldly mind"],"special_abilities":[{"type":"Angled Entry","kind":"Su","details":"Lesser hounds of Tindalos may use greater teleport (self only) once per round as a swift action and plane shift (self only) 3/day as a standard action (caster level 7th). This ability is otherwise identical to the angled entry ability of a regular hound of Tindalos."},{"type":"Otherworldly Mind","kind":"Ex","details":"Any non-outsider attempting to read the thoughts of a hound of Tindalos or communicate with it telepathically takes 5d4 points of nonlethal damage and must make a DC 16 Will save or become confused for 2d4 rounds. This is a mind-affecting effect. The save DC is Charisma-based."},{"type":"Ripping Gaze","kind":"Su","details":"5d4 slashing damage, 30 feet, Fortitude DC 16 negates. A creature that succeeds on its save is immune to that hound's gaze for 24 hours. This ability is otherwise identical to the ripping gaze ability of a regular hound of Tindalos."}],"before_combat":"The hound of Tindalos casts invisibility on itself then lurks in the temple, analyzing the PCs. If the akata or undead attack, the hound immediately joins the fight; otherwise, it waits for the PCs to study the temple and strikes when their guard is down.","during_combat":"The hound of Tindalos attacks from invisibility, appearing only when it can subject the PCs to its ripping gaze. The hound makes use of its angled entry ability to leap around the room, attack from unexpected angles, and avoid retaliation.","morale":"If reduced to 10 or fewer hit points, the hound of Tindalos casts plane shift to escape. It returns after a few rounds and remains invisible, stalking the PCs. If discovered, it flees again and doesn't come back until the PCs leave.","source":"PFS S5-16"},{"name":"Kafar","cr":6,"xp":2400,"race":"human","age_category":"Adult","classes":[{"class":"alchemist","level":5},{"class":"Aspis agent","level":2}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":21,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+5 armor, +2 Dex, +4 natural","hp":52,"hd":"7d8+1d10+12","hd_value":8,"fort":9,"ref":10,"will":5,"save_mods":"+4 vs. poison","defensive_abilities":["conceal thoughts","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk sickle +9 (1d6+2 plus blue whinnis poison) or mwk whip +9 (1d3+2 nonlethal)","ranged":"dart +8 (1d4+2 plus blue whinnis poison) or bomb +8 (3d6+2 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"8/day, 3d6+2 fire, DC 14"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":5,"extractsprepared":[{"spell_level":2,"spells":[{"spell":"delay poison","used":true},{"spell":"false life","used":true},{"spell":"spider climb"}]},{"spell_level":1,"spells":[{"spell":"ant haul","used":true},{"spell":"cure light wounds"},{"spell":"detect secret doors"},{"spell":"endure elements","used":true},{"spell":"shield"}]}],"strength":14,"dexterity":14,"constitution":12,"intelligence":14,"wisdom":10,"charisma":13,"baseatk":4,"cmb":8,"cmd":18,"feats":[{"feat":"Brew Potion"},{"feat":"Cosmopolitan (Diplomacy, Intimidate)"},{"feat":"Exotic Weapon Proficiency (whip)"},{"feat":"Extra Discovery"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Bluff)"},{"feat":"Throw Anything"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Bluff","value":16},{"skill":"Craft (alchemy)","value":12},{"skill":"Craft (traps)","value":12},{"skill":"Diplomacy","value":11},{"skill":"Disable Device","value":16},{"skill":"Disguise","value":8},{"skill":"Intimidate","value":13},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (history)","value":12},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":6},{"skill":"Sleight of Hand","value":8},{"skill":"Survival","value":6}],"languages":["Common","Aklo","Draconic","Gnoll","Kelish","Osiriani","Undercommon"],"sq":["agency secret (conceal thoughts)","alchemy (alchemy crafting +5, identify potions)","discoveries (concentrate poison, smoke bomb, stink bomb)","mask alignment","mutagen (+4/-2, +2 natural, 50 minutes)","poison use","swift alchemy","trap sense +1","trapfinding"],"special_abilities":[{"type":"Conceal Thoughts","kind":"Su","details":"If targeted with detect thoughts or a similar effect, Kafar may choose what thoughts are detected, while his true thoughts remain private. This doesn't affect mind-affecting effects other than thought-reading."},{"type":"Concentrated Blue Whinnis Poison","kind":"Ex","details":"Kafar has created a concentrated dose of blue whinnis poison (injury; save Fort DC 16; frequency 1/ round for 3 rounds; initial effect 1 Con damage; secondary effect unconsciousness for 1d3 hours; cure 1 save)."},{"type":"Mask Alignment","kind":"Su","details":"At 2nd level, as a standard action, Kafar can alter his alignment aura to deceive effects that detect alignment. He may choose to be detected as any specific alignment or detect as no alignment at all. This affects only alignment detection, not effects that cause harm or are otherwise based on alignment. This effect lasts until he dismisses it or changes his alignment aura again. At this time, Kafar detects as being lawful neutral."}],"gear":"+1 mithral chain shirt, mwk sickle, mwk whip, darts (4), cloak of resistance +1, blue whinnis poison (4 doses), concentrated blue whinnis poison (1 dose), formula book (contains all prepared extracts plus bulls strength, comprehend languages, crafter's fortune, disguise self, and expeditious retreat), marbles (4), masterwork thieves' tools, pocketed scarf, 173 gp, potion of barkskin, potion of cure serious wounds, tanglefoot bag (3)","before_combat":"Kafar wants to ensure he is prepared in the event that his meeting with the Diamond Sage goes poorly. To this end, he recently consumed his extracts of ant haul, delay poison, endure elements, and false life, as well as his Strength mutagen and a potion of barkskin. Nefti has also cast heroism on him.","during_combat":"Kafar throws a stink bomb at the PCs and enters the smoke cloud to strike with a poisoned sickle, using his delay poison extract to protect himself from the cloud's nauseating effect. He aims to knock the PCs out just long enough to allow him to deliver the topaz gem.","morale":"Kafar offers parley if reduced to 12 or fewer hit points or if Nefti falls or surrenders.","base_statistics":"When not under the effects of his mutagen, barkskin, false life, and heroism, Kafar's statistics are AC 17, flat-footed 15; hp 42; Fort +7, Ref +8, Will +3; Melee mwk sickle +5 (1d6) or mwk whip +5 (1d3 nonlethal); Ranged dart +6 (1d4) or bomb +6 (3d6+3 fire); Str 10, Int 16; CMB +4; CMD 16; Skills Appraise +11, Bluff +14, Craft (alchemy) +11, Craft (traps) +11, Diplomacy +9, Disable Device +14, Disguise +6, Intimidate +11, Knowledge (arcana) +9, Knowledge (history) +11, Perception +10, Sense Motive +4, Sleight of Hand +6, Survival +4","source":"PFS S5-16, Pathfinder Campaign Setting: Paths of Prestige 8"},{"name":"Nefti","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"bard","level":5}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex","hp":41,"hd":"5d8+15","hd_value":5,"fort":4,"ref":8,"will":9,"save_mods":"+4 vs. bardic performance, languagedependent,  and sonic","speed":[{"type":"land","speed":30}],"melee":"+1 Human bane sap +7 (1d6+2 nonlethal)","ranged":"mwk shortbow +8 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 16 rounds/day","details":"countersong, distraction, fascinate [DC 16], inspire competence +2, inspire courage +2"}],"spellsknown_caster":"bard","spellsknown_caster_level":5,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"calm emotions"},{"spell":"heroism"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"hideous laughter"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"prestidigitation"}]}],"strength":12,"dexterity":14,"constitution":12,"intelligence":14,"wisdom":13,"charisma":18,"baseatk":3,"cmb":6,"cmd":16,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Spell Focus (enchantment)"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Climb","value":8},{"skill":"Escape Artist","value":12},{"skill":"Knowledge (dungeoneering)","value":10},{"skill":"Knowledge (engineering)","value":10},{"skill":"Knowledge (geography)","value":10},{"skill":"Knowledge (local)","value":14},{"skill":"Linguistics","value":8},{"skill":"Perception","value":9},{"skill":"Perform (act)","value":14},{"skill":"Perform (oratory)","value":11},{"skill":"Perform (wind)","value":11},{"skill":"Sleight of Hand","value":8},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":12},{"skill":"Use Magic Device","value":14}],"languages":["Common","Infernal","Kelish","Osiriani"],"sq":["bardic knowledge +2","exceptional stats","lore master 1/day","versatile performance (act)"],"special_abilities":[{"type":"Exceptional Stats","kind":"Ex","details":"Nefti is a prodigy of the Aspis Consortium, and the organization recruited him and began training him for service early in his life. As a result, his ability scores were generated using 25 points, rather than the standard 15 points used to create most NPCs. This modification increases his total CR by 1."}],"gear":"mwk studded leather, +1 Human bane sap, mwk shortbow with 20 arrows, shortsword with falsebottomed scabbard, 133 gp, potion of cure moderate wounds, potion of delay poison, scrolls of comprehend languages (2), acid (2)","before_combat":"Following Kafar's hunch about their impending meeting with the Diamond Sage, Nefti has cast heroism on himself and Kafar.","during_combat":"Nefti uses his spells to inconvenience and incapacitate the PCs, sparing a moment to cast mirror image if attacked. If his foes disappear into one of Kafar's stink bombs, Nefti drinks his potion of delay poison, inspires courage, and joins his partner in the melee.","morale":"Nefti surrenders if reduced to 8 or fewer hit points or if Kafar attempts to parley with the PCs. If Kafar is unconscious, Nefti offers to parley. Should the PCs refuse to negotiate, Nefti casts calm emotions and attempts to settle matters diplomatically.","base_statistics":"When not under the effects of his heroism, Nefti's statistics are Fort +2, Ref +6, Will +7; Melee +1 Human bane sap +5 (1d6+2); CMB +4; Skills Acrobatics +10, Climb +6, Escape Artist +10, Knowledge (dungeoneering) +8, Knowledge (engineering) +8, Knowledge (geography) +8, Knowledge (local) +12, Linguistics +6, Perception +7, Perform (act) +12, Perform (oratory) +9, Perform (wind) +9, Sleight of Hand +6, Spellcraft +6, Stealth +10, Use Magic Device +12","source":"PFS S5-16"},{"name":"Kafar Subtier 6-7","cr":9,"xp":6400,"race":"human","age_category":"Adult","classes":[{"class":"alchemist","level":8},{"class":"Aspis Agent","level":2}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":23,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+5 armor, +1 deflection, +2 Dex, +5 natural","hp":58,"hd":"10d8+10","hd_value":10,"fort":12,"ref":13,"will":7,"save_mods":"+6 vs. poison","speed":[{"type":"land","speed":30}],"melee":"+1 sickle +12 (1d6+3 plus blue whinnis poison) or mwk whip +12 (1d3+2 nonlethal)","ranged":"dart +11 (1d4+2 plus blue whinnis poison) or bomb +11 (4d6+2 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"11/day, 4d6+2 fire, DC 16"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":8,"extractsprepared":[{"spell_level":3,"spells":[{"spell":"gaseous form"},{"spell":"haste"},{"spell":"nondetection","used":true}]},{"spell_level":2,"spells":[{"spell":"bull's strength"},{"spell":"delay poison","used":true},{"spell":"detect thoughts"},{"spell":"false life","used":true},{"spell":"spider climb"}]},{"spell_level":1,"spells":[{"spell":"ant haul","used":true},{"spell":"cure light wounds"},{"spell":"detect secret doors"},{"spell":"endure elements","used":true},{"spell":"shield"}]}],"strength":14,"dexterity":14,"constitution":12,"intelligence":14,"wisdom":10,"charisma":14,"baseatk":7,"cmb":11,"cmd":22,"feats":[{"feat":"Blind-Fight"},{"feat":"Brew Potion"},{"feat":"Cosmopolitan"},{"feat":"Exotic Weapon Proficiency (whip)"},{"feat":"Extra Discovery"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Bluff)"},{"feat":"Throw Anything"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Bluff","value":23},{"skill":"Craft (alchemy)","value":12},{"skill":"Craft (traps)","value":12},{"skill":"Diplomacy","value":12},{"skill":"Disable Device","value":17},{"skill":"Disguise","value":9},{"skill":"Intimidate","value":17},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (history)","value":12},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":12},{"skill":"Sleight of Hand","value":12},{"skill":"Spellcraft","value":9},{"skill":"Survival","value":9}],"languages":["Common","Aklo","Draconic","Gnoll","Kelish","Osiriani","Undercommon"],"sq":["agency secret (conceal thoughts)","alchemy (alchemy crafting +8, identify potions)","discoveries (concentrate poison, fast bombs, smoke bomb, sticky poison [2 strikes], stink bomb)","mask alignment","mutagen (+4/-2, +2 natural, 80 minutes)","poison use","swift alchemy","swift poisoning trapfinding","trap sense +1"],"special_abilities":[{"type":"Conceal Thoughts","kind":"Su","details":"If targeted with detect thoughts or a similar effect, Kafar may choose what thoughts are detected, while his true thoughts remain private. This doesn't affect mind-affecting effects other than thought-reading."},{"type":"Concentrated Blue Whinnis Poison","kind":"Ex","details":"Kafar has created a concentrated dose of blue whinnis poison (injury; save Fort DC 16; frequency 1/round for 3 rounds; initial effect 1 Con damage; secondary effect unconsciousness for 1d3 hours; cure 1 save)."},{"type":"Mask Alignment","kind":"Su","details":"At 2nd level, as a standard action, Kafar can alter his alignment aura to deceive effects that detect alignment. He may choose to be detected as any specific alignment or detect as no alignment at all. This affects only alignment detection, not effects that cause harm or are otherwise based on alignment. This effect lasts until he dismisses it or changes his alignment aura again. At this time, Kafar detects as being lawful neutral."}],"gear":"+1 mithral chain shirt, +1 sickle, mwk whip, darts (4), cloak of resistance +2, ring of protection +1, blue whinnis poison (4 doses), concentrated blue whinnis poison (1 dose), formula book (contains all prepared extracts plus cat's grace, comprehend languages, crafter's fortune, disguise self, expeditious retreat, and heroism), marbles (4), masterwork thieves' tools, pocketed scarf, 23 gp, potion of barkskin (CL 6th), potion of cure serious wounds, tanglefoot bag (3)","before_combat":"Kafar wants to ensure he is prepared in the event that his meeting with the Diamond Sage goes poorly. To this end, he recently consumed his extracts of ant haul, delay poison, endure elements, and false life, as well as his Strength mutagen and a potion of barkskin. Nefti has also cast heroism on him.","during_combat":"Kafar throws a stink bomb at the PCs and enters the smoke cloud to strike with a poisoned sickle, using his delay poison extract to protect himself from the cloud's nauseating effect. He aims to knock the PCs out just long enough to allow him to deliver the topaz gem.","morale":"Kafar offers parley if reduced to 15 or fewer hit points or if Nefti falls or surrenders.","base_statistics":"When not under the effects of his mutagen, barkskin, false life, and heroism, Kafar's statistics are AC 17, flat-footed 15; hp 42; Fort +7, Ref +8, Will +3; Melee +1 sickle +8/+3 (1d6+1) or mwk whip +8/+3 (1d3 nonlethal); Ranged dart +9 (1d4) or bomb +9/+4 (4d6+3 fire); Str 10, Int 16; CMB +7; CMD 20; Skills Appraise +11, Bluff +21, Craft (alchemy) +11, Craft (traps) +11, Diplomacy +10, Disable Device +15, Disguise +7, Intimidate +15, Knowledge (arcana) +9, Knowledge (history) +11, Perception +13, Sense Motive +10, Sleight of Hand +10, Spellcraft +8, Survival +7","source":"PFS S5-16"},{"name":"Nefti Subtier 6-7","cr":8,"xp":4800,"race":"human","age_category":"Adult","classes":[{"class":"bard","level":8}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":17,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+4 armor, +1 deflection, +2 Dex","hp":60,"hd":"8d8+21","hd_value":8,"fort":6,"ref":11,"will":12,"save_mods":"+4 vs. bardic performance,  language-dependent, and sonic","speed":[{"type":"land","speed":30}],"melee":"+1 Human bane sap +10 (1d6+2 nonlethal)","ranged":"mwk shortbow +11 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 22 rounds/day","details":"move action; countersong, dirge of doom [DC 18], distraction, fascinate [DC 18], inspire competence +3, inspire courage +2, suggestion [DC 18]"}],"spellsknown_caster":"bard","spellsknown_caster_level":8,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"confusion"},{"spell":"deep slumber"},{"spell":"glibness"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"calm emotions"},{"spell":"glitterdust"},{"spell":"heroism"},{"spell":"mirror image"},{"spell":"misdirection"},{"spell":"shatter"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"hideous laughter"},{"spell":"obscure object"},{"spell":"remove fear"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"prestidigitation"}]}],"strength":12,"dexterity":14,"constitution":12,"intelligence":14,"wisdom":13,"charisma":19,"baseatk":6,"cmb":9,"cmd":20,"feats":[{"feat":"Greater Spell Focus (enchantment)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Spell Focus (enchantment)"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Climb","value":11},{"skill":"Escape Artist","value":15},{"skill":"Knowledge (dungeoneering)","value":12},{"skill":"Knowledge (engineering)","value":12},{"skill":"Knowledge (geography)","value":12},{"skill":"Knowledge (local)","value":19},{"skill":"Linguistics","value":8},{"skill":"Perception","value":9},{"skill":"Perform (act)","value":17},{"skill":"Perform (oratory)","value":17},{"skill":"Perform (wind)","value":11},{"skill":"Sleight of Hand","value":8},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":15},{"skill":"Use Magic Device","value":17}],"languages":["Common","Infernal","Kelish","Osiriani"],"sq":["bardic knowledge +4","exceptional stats","lore master 1/day","versatile performance (act, oratory)"],"special_abilities":[{"type":"Exceptional Stats","kind":"Ex","details":"Nefti is a prodigy of the Aspis Consortium, and the organization recruited him and began training him for service early in his life. As a result, his ability scores were generated using 25 points, rather than using the standard 15 point buy used to create most NPCs. This modification increases his total CR by 1."},{"type":"Favored Class Bonus","kind":"Ex","details":"Nefti has selected the Human bard favored class option (Advanced Player's Guide 22) three times. As a result, he knows one additional 1st-level spell and two additional 2nd-level spells."}],"gear":"+1 studded leather, +1 Human bane sap, mwk shortbow with 20 arrows, shortsword with false-bottomed scabbard, cloak of resistance +1, ring of protection +1, 273 gp, potion of cure moderate wounds, potion of delay poison, potion of invisibility, scrolls of comprehend languages (2), acid (2)","before_combat":"Following Kafar's hunch about their impending meeting with the Diamond Sage, Nefti has cast glibness, heroism, and misdirection (using a beetle he found earlier)  on himself and has cast heroism on Kafar.","during_combat":"Nefti uses his spells to inconvenience and incapacitate the PCs, sparing a moment to cast mirror image if attacked. If his foes disappear into one of Kafar's stink bombs, Nefti drinks his potion of delay poison, inspires courage, and joins his partner in the melee.","morale":"Nefti surrenders if reduced to 12 or fewer hit points or if Kafar attempts to parley with the PCs. If Kafar is unconscious, Nefti offers to parley. Should the PCs refuse to negotiate, Nefti casts calm emotions to settle matters diplomatically.","base_statistics":"When not under the effects of his heroism, Nefti's statistics are Fort +4, Ref +9, Will +10; Melee +1 Human bane sap +8/+3 (1d6+2); CMB +7; Skills Acrobatics +13, Climb +9, Escape Artist +13, Knowledge (dungeoneering) +10, Knowledge (engineering) +10, Knowledge (geography) +10, Knowledge (local) +17, Linguistics +6, Perception +7, Perform (act) +15, Perform (oratory) +15, Perform (wind) +9, Sleight of Hand +6, Spellcraft +6, Stealth +13, Use Magic Device +15","source":"PFS S5-16"},{"name":"Mythic Glass Golem","cr":10,"xp":9600,"race":"Mythic Glass Golem","age_category":"Adult","alignment":"N","size":"Large","type":"construct","sub_types":["mythic"],"init":0,"senses":["darkvision 60 ft.","low-light vision"],"ac":26,"ac_touch":9,"ac_flat_footed":26,"ac_mods":"+17 natural, -1 size","hp":136,"hd":"12d10+70","hd_value":12,"fort":4,"ref":4,"will":4,"defensive_abilities":["DR 10/adamantine and epic","mirrorsight","reflect spells","second save"],"immunities":["construct traits","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +17 (2d8+9 plus bleed)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1d8"},{"type":"blinding brightness"},{"type":"mythic power","details":"4/day, surge +1d8"},{"type":"powerful blows","details":"slam"},{"type":"rend","details":"2 slams, 2d8 bleed"}],"strength":22,"dexterity":11,"wisdom":11,"charisma":1,"baseatk":12,"cmb":19,"cmd":29,"special_abilities":[{"type":"Dazzling Brightness","kind":"Ex","details":"A mythic glass golem in an area of bright light blinds any creature within 30 ft. that can see it for 1 round (Fortitude DC 16 negates). Once a creature makes this save, it is dazzled for 1 round and is immune to that golem's brightness for 24 hours. The DC is Constitution-based."},{"type":"Immune to Magic","kind":"Ex","details":"A mythic glass golem is immune to any spell or spell-like ability that allows spell resistance.In addition, certain spells and effects function differently against a mythic glass golem, as noted below. • A shatter spell damages a mythic glass golem as if it were a crystalline creature. • A keen edge spell affects all of a mythic glass golem's slam attacks as if they were slashing weapons. • A mythic magical attack that deals cold damage slows a mythic glass golem (as the slow spell) for 3 rounds (no saving throw). • A magical attack that deals fire damage ends any slow effect on the golem and heals 1 point of damage for each 3 points of damage the attack would normally deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A mythic glass golem gets no saving throw against fire effects."},{"type":"Mirrorsight","kind":"Ex","details":"A mythic glass golem's surface reflects images of nearby creatures-even invisible creatures-like a multifaceted mirror. When the mythic glass golem is attacked while denied its Dexterity bonus to AC or while flanked, as an immediate action, the golem can spend one use of mythic power to gain the benefits of all-around vision and see invisibility until the beginning of its next turn. The golem can use this ability even if it would not otherwise be aware of the attack."},{"type":"Reflect Spells","kind":"Ex","details":"As a free action, once every 1d4 rounds, a mythic glass golem can align its internal structure to enhance its resistance to magic for 1 round. During this time, the golem reflects spells (even spells that function differently against the golem as described in its immune to magic ability) as if under the effects of spell turning."}],"during_combat":"The mythic glass golem focuses its attacks on the PC that dealt it the most damage since its last turn.","morale":"The mythic glass golem fights until destroyed or until all four gem carvings are illuminated in the proper order.","source":"PFS S5-16"},{"name":"Xenarth","cr":10,"xp":9600,"race":"bulette","age_category":"Adult","alignment":"CE","size":"Huge","type":"outsider","sub_types":["chaotic","demon","evil","native"],"init":6,"senses":["darkvision 60 ft.","tremorsense 60 ft."],"ac":24,"ac_touch":10,"ac_flat_footed":22,"ac_mods":"+2 Dex, +14 natural, -2 size","hp":148,"hd":"11d10+88","hd_value":11,"fort":13,"ref":9,"will":9,"defensive_abilities":["demon ichor"],"dr":"10/cold iron and good","immunities":["electricity and poison"],"resists":["acid 10","cold 10","fire 10"],"sr":21,"speed":[{"type":"burrow","speed":20},{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"bite +19 (2d6+13 plus poison/19-20), 2 claws +19 (1d8+9)","space":"15 ft.","reach":"10 ft.","strength":29,"dexterity":15,"constitution":27,"intelligence":6,"wisdom":10,"charisma":6,"baseatk":11,"cmb":22,"cmd":34,"cmd_special":"38 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite, claw)"}],"skills":[{"skill":"Acrobatics","value":2,"special":"+4 when jumping"},{"skill":"Climb","value":31},{"skill":"Perception","value":20},{"skill":"Stealth","value":8},{"skill":"Survival","value":14}],"languages":["Abyssal","telepathy 100 ft."],"special_abilities":[{"type":"Demon Ichor","kind":"Su","details":"A slimy red ichor coats the xenarth's armored plates. Any weapon that touches a xenarth takes 3d8 points of acid damage from the corrosive demon essence, and the weapon's hardness doesn't reduce this damage. A magic weapon may attempt a DC 23 Reflex save to avoid taking this damage. A creature that strikes a xenarth with an unarmed attack, unarmed strike, melee touch spell, or natural weapon takes this damage unless the attacker succeeds at a DC 23 Reflex save. The save DCs are Constitution-based."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d3 Con damage; cure 2 saves. The save DC is Constitution-based."},{"type":"Savage Bite","kind":"Ex","details":"A xenarth's bite is particularly dangerous. It applies 1-1/2 times its Strength modifier to damage inflicted with its bite attack, and it threatens a critical hit on a 19-20."}],"source":"PFS S5-17, Pathfinder Campaign Setting: Dungeon Denizens Revisited 8"},{"name":"Morlock Chieftain","cr":6,"xp":2400,"race":"Morlock","age_category":"Adult","classes":[{"class":"barbarian","level":4}],"alignment":"CE","size":"Medium","type":"monstrous humanoid","init":10,"senses":["darkvision 120 ft.","scent"],"ac":16,"ac_touch":15,"ac_flat_footed":9,"ac_mods":"+6 Dex, +1 dodge, +1 natural, -2 rage","hp":93,"hd":"3d10+4d12+46","hd_value":7,"fort":11,"ref":12,"will":8,"save_mods":"+3 vs. magic","defensive_abilities":["trap sense +1","uncanny dodge"],"immunities":["disease","poison"],"weaknesses":["light blindness"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":50}],"melee":"club +13 (1d6+6), bite +13 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"leap attack"},{"type":"rage","details":"14 rounds/day"},{"type":"rage powers","details":"superstition +3, surprise accuracy +2"},{"type":"sneak attack","details":"+1d6"},{"type":"swarming"}],"strength":22,"dexterity":23,"constitution":22,"intelligence":7,"wisdom":14,"charisma":4,"baseatk":7,"cmb":13,"cmd":28,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":21,"special":"+8 when jumping"},{"skill":"Climb","value":30},{"skill":"Perception","value":7},{"skill":"Ride","value":13},{"skill":"Stealth","value":13}],"languages":["Undercommon"],"sq":["expert climber","fast movement"],"gear":"club","before_combat":"The morlock chieftain is under the effects of the kalavakus demon's enslave ability.","during_combat":"The morlock chieftain fights savagely, preferring targets already swarmed by other morlocks.","morale":"The morlock chieftain fights to the death, fearful of what other torments Irorstikal might inflict. When slain, the morlock's essence heals the enslaving kalavakus. If Irorstikal is slain, the chieftain spends one round trying to convince its subordinates to retreat, but it then resumes fighting.","base_statistics":"When not raging, the chieftain's statistics are AC 18, touch 17, flat-footed 11; hp 79; Fort +9, Will +6; Melee club +11/+6 (1d6+4), bite +11 (1d6+7); Str 18, Con 18; CMB +11, CMD 28; Skills Climb +28.","source":"PFS S5-17"},{"name":"Damaged Stone Golem","cr":9,"xp":6400,"race":"Damaged Stone Golem","age_category":"Adult","alignment":"N","size":"Large","type":"construct","init":-1,"senses":["darkvision 60 ft.","low-light vision"],"ac":23,"ac_touch":8,"ac_flat_footed":23,"ac_mods":"-1 Dex, +15 natural, -1 size","hp":90,"hd":"11d10+30","hd_value":11,"fort":3,"ref":2,"will":3,"dr":"5/adamantine","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":20}],"melee":"2 slams +18 (2d10+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"slow"}],"strength":26,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":11,"cmb":20,"cmd":29,"special_abilities":[{"type":"Immunity to Magic","kind":"Ex","details":"A stone golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature as noted below. A transmute rock to mud spell slows the golem (as the slow spell) for 2d6 rounds, with no saving throw, while transmute mud to rock heals all of its lost hit points. A stone to flesh spell doesn't actually change the golem's structure but it negates its damage reduction and immunity to magic for 1 full round."},{"type":"Slow","kind":"Su","details":"A stone golem can use a slow effect, as the spell, as a free action every 2 rounds. The effect has a range of 10 ft. in a burst centered on the golem and a duration of 7 rounds, requiring a successful DC 15 Will save to negate. The save DC is Constitution based."}],"source":"PFS S5-17"},{"name":"Relentless Hill Giant Zombie","cr":6,"xp":2400,"race":"hill giant","age_category":"Adult","alignment":"NE","size":"Large","type":"undead","sub_types":["giant"],"templates_applied":"relentless@zombie","init":0,"senses":["darkvision 60 ft."],"ac":12,"ac_touch":9,"ac_flat_footed":12,"ac_mods":"+3 natural, -1 size","hp":77,"hd":"14d8+14","hd_value":14,"fort":4,"ref":4,"will":9,"immunities":["undead traits"],"speed":[{"type":"climb","speed":20},{"type":"land","speed":40}],"melee":"2 slams +17 (1d8+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"quick strikes"}],"strength":27,"dexterity":10,"wisdom":10,"charisma":10,"baseatk":10,"cmb":19,"cmd":29,"feats":[{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Climb","value":16}],"special_abilities":[{"type":"Quick Strikes","kind":"Ex","details":"Whenever a relentless hill giant zombie takes a full-attack action, it can make one additional slam attack at its highest base attack bonus."}],"source":"PFS S5-18, Pathfinder RPG Bestiary 150, 288, Pathfinder Campaign Setting: Classic Horrors Revisited 55"}];
